"""The meeting document, in the PI's voice: the approach and where it comes from, the model with its variables drawn first, the data and
what was done to it, results with takeaways, the five figures, the tables, the supplementary list, and directions for writing.
Output: paper/METHODS_AND_RESULTS.docx"""
import json, pandas as pd
from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt
H = Path(__file__).resolve().parent; P = H / "paper"; D = H / "data_clean"; FIG = H / "figures"; FOLDER = H.name; MD = []
import os
s7 = json.load(open(D / "step7_summary.json")); nb = json.load(open(D / "nest_bayes.json")); ab = json.load(open(D / "adcp_single_beam.json")); cal = json.load(open(D / "uncertainty_calibration.json")); fq = json.load(open(D / "field_qc.json")); rr = json.load(open(D / "step6_reach_rating.json")); nh = json.load(open(D / "nest_habitat_model.json"))
t3 = pd.read_csv(P / "table3_scores.csv"); t2 = pd.read_csv(P / "table2_parameters.csv"); t4 = pd.read_csv(P / "table4_ablations.csv")
doc = Document(); st = doc.styles["Normal"]; st.font.name = "Calibri"; st.font.size = Pt(10.5)
for sec in doc.sections: sec.left_margin = sec.right_margin = Inches(1); sec.top_margin = sec.bottom_margin = Inches(0.9)
def h(t, lvl=1): doc.add_heading(t, level=lvl); MD.append(f"\n{'#' * (lvl + 1)} {t}\n")
def p(t, italic=False): par = doc.add_paragraph(); r = par.add_run(t); r.italic = italic; MD.append((f"*{t}*" if italic else t) + "\n"); return par
def bullet(t, lead=None):
    par = doc.add_paragraph(style="List Bullet")
    if lead: r = par.add_run(lead + " "); r.bold = True
    par.add_run(t); MD.append(f"- **{lead}** {t}" if lead else f"- {t}")
def fig(path, caption, width=6.5):
    doc.add_picture(str(path), width=Inches(width)); c = doc.add_paragraph(); r = c.add_run(caption); r.italic = True; r.font.size = Pt(9); MD.append(f"\n![{caption.split('.')[0]}]({os.path.relpath(path, P)})\n\n*{caption}*\n")
def table(df, widths=None, font=8.5):
    t = doc.add_table(rows=1, cols=len(df.columns)); t.style = "Light Grid Accent 1"
    for j, c in enumerate(df.columns): cell = t.rows[0].cells[j]; cell.text = ""; run = cell.paragraphs[0].add_run(str(c)); run.bold = True; run.font.size = Pt(font)
    for _, row in df.iterrows():
        cells = t.add_row().cells
        for j, v in enumerate(row.values): cells[j].text = ""; run = cells[j].paragraphs[0].add_run("" if pd.isna(v) else (f"{v:.3f}" if isinstance(v, float) else str(v))); run.font.size = Pt(font)
    if widths:
        for row in t.rows:
            for j, w in enumerate(widths): row.cells[j].width = Inches(w)
    doc.add_paragraph(); cols = list(df.columns); MD.append("\n| " + " | ".join(cols) + " |\n|" + "---|" * len(cols) + "\n" + "\n".join("| " + " | ".join("" if pd.isna(v) else (f"{v:.3f}" if isinstance(v, float) else str(v).replace("|", "/").replace("\n", " ")) for v in row.values) + " |" for _, row in df.iterrows()) + "\n")
vc = nb["velocity_coef_per_m_s"]; ds = cal["discrepancy_split"]
# ---------------------------------------------------------------- title
doc.add_heading("A season-long velocity record for a river reach from one survey campaign, one stage sensor and one ADCP", 0); MD.append("# A season-long velocity record for a river reach from one survey campaign, one stage sensor and one ADCP\n")
p(f"Methods, results and figure plan for the paper. Middle reach of the Huron River, Michigan. Prepared 22 September 2026 from the analysis in {FOLDER}/, which reruns end to end in about ten minutes (RERUN.md) and reproduced every number below on a clean rerun. This is the guide for our meeting and the skeleton for the writing. The logbook (LOGBOOK.md, entries 0 to 24) has every intermediate decision and number, should a question go deeper than this document.", italic=True)
# ---------------------------------------------------------------- 1
h("1. The claim")
p("In an era in which a stage sensor costs less than a day of field work and reports every ten minutes, velocity, the quantity on which habitat and most operating decisions actually depend, is still measured by hand on a handful of days a year. This raises the question: how far can one stage record and one survey campaign be pushed? On a 0.7 km reach we contend that they can be pushed to the depth-averaged velocity of every surveyed cross-section at every hour of two seasons, with a band that holds up when whole sections and whole days are held out (CRPS 0.31 against 0.41 for the reach mean, and 20 of 20 section means on held-out days inside the band), when a fixed acoustic instrument is compared through a season (level ratio 0.86, 41 mm/s), and when discharge is checked between sections (20 discharges on one rating, 6% scatter). From that record follows an ecological number, the reach's mean nesting suitability, with the rule learned from the fish rather than assumed and with its own band. The stage sensor is effectively turned into a velocity sensor for the whole reach.")
# ---------------------------------------------------------------- 2
h("2. Where this comes from, and why it looks different from the notebooks")
p("The notebooks learned velocity directly, as a Gaussian process of stage and two channel coordinates, on every row of the survey sheets, and scored it by random cross-validation. Three things made that fragile. Rows of different kinds were mixed (single readings taken while walking, nest readings, transect profiles). The height column meant different things in the two years. Random folds let neighbouring readings leak, so the skill looked far higher than it turned out to be on a new day (R² 0.55 against 0.03). The rebuild keeps the idea, a GP over the reach driven by the stage record, and changes what the GP is asked to learn and how it is tested.")
p("The physical reduction is the heart of it. Rather than learning velocity, we learn a property of the place. Each profile of three to five readings collapses to one number by the log law of the wall, the amplitude a (Section 4 and Figure M draw every variable). A one-parameter stage law then removes the day: A = a / (stage − h0). A does not depend on the day, which is why 257 locations are enough. In the language of the USGS index-velocity methods this is a separable model, a(x, t) = A(x) g(stage(t)): one static field, one time series, and a law between them. The GP learns only A, on measured channel geometry, and what it learns turns out to be mostly bank distance, that is, at-a-station hydraulic geometry.")
p("Two further choices follow from the data rather than from taste. The exponent of the stage law is not pinned by eleven survey days: several (h0, γ) pairs fit equally well. As such, we keep the whole set and carry it into the uncertainty, and the band widens above the surveyed stage range where the laws diverge. And the ecological rule is learned rather than assumed: the nests are asked what they chose relative to what was available, with the published USFWS spawning curve as a weak prior, so the rule comes out with a band and travels through the same chain as the velocities.")
p("Validation is the other departure. Sections are held out one at a time, days are held out one at a time, the readings on held-out days are predicted at their own heights, the section means on held-out days are checked against the band, the ADCP is compared through a whole season at its own cell, and discharge is checked for continuity between sections. Scores are MAE, CRPS and coverage in physical units. R² on a narrow test set is what misled the first pass, and random folds appear once, as the cautionary comparison.")
# ---------------------------------------------------------------- 3 the model, with the variables figure up front
h("3. The model, with its variables")
p("Figure M is the one to have open when the questions start. It is drawn from the data: one real profile, the real survey days, one real section, and the chain as it runs.")
fig(FIG / "17_model_variables.png", "Figure M. The model's variables. (a) One profile becomes one number: the readings at heights z above the bed follow v(z) = a ln(z/z0), with z0 the height at which the law reaches zero (11 mm, one value for the reach) and a the amplitude (one number per location, a = u*/κ in the friction language); the depth-averaged velocity is v̄ = a (ln(h/z0) − 1). (b) The amplitude rises with the day's stage; a = A (stage − h0)^γ removes it, with h0 the stage at which the amplitude vanishes (0.45 m) and γ = 1 the adopted exponent; six other (h0, γ) pairs fit the survey days as well and form the law set. A, the place factor, is what the GP learns. (c) A across one section at the reference stage, with the GP's inputs. (d) From the sensor to the ecological number, every two hours.", width=6.6)
p("A glossary, for the same purpose:")
gl = pd.DataFrame([("z", "height above the bed of a reading", "measured (0.05 to 0.6 m)"), ("z0", "roughness scale: the height at which the log law reaches zero", "11 mm for the reach, fitted; drawn 7 to 16 mm in the chain"), ("v(z)", "velocity at height z", "measured, 3 to 5 per location"), ("a", "the amplitude of the log law at a location, on its day", "fitted per location, with its own error from the readings' spread"), ("h", "local water depth", "stage minus bed, on the sensor datum"), ("v̄", "depth-averaged velocity, a (ln(h/z0) − 1)", "derived"), ("stage", "the sensor's water level, every 10 min", "measured, cleaned"), ("h0, γ", "the stage law's offset and exponent", "0.45 m and 1.0 adopted; a set of seven pairs carried"), ("A", "the place factor, a / (stage − h0)^γ", "the GP's target; one static field"), ("d, x, ...", "the GP's inputs: bank distance, along and across position, relative depth, section mean depth, lateral bed slope", "measured geometry"), ("S(v), E", "relative nesting suitability exp(b_v v), and its reach mean", "b_v learned from the nests with a weak prior")], columns=["symbol", "meaning", "where it comes from"]); table(gl, widths=[0.9, 3.2, 2.4], font=8.5)
h("3.1 From readings to the amplitude a", 2)
p(f"For each location the readings at heights z are fitted by v = a ln(z/z0), with one roughness scale for the reach, z0 = {fq['z0_m']*1000:.0f} mm, from a pooled grid search on the profiles with three or more readings (the fit is flat between 7 and 16 mm). The spread of the readings' implied amplitudes gives each location its own measurement error, which the GP uses as fixed noise. A transfer check, predicting the 1 ft reading of each profile from its other readings, gives 30 mm/s on 124 profiles. Simply put, every location becomes one physical number with an error bar.")
h("3.2 The stage law and the place factor A", 2)
p("On each survey day the amplitudes rise with stage. Divided by (stage − 0.45 m)^0.75 they do not (Figure 1d, e). Each day held out and predicted from the others, the day's mean residual has sd 0.30 in log before the law and 0.14 after. The day-out score is flat across (h0, γ) pairs from (0.35, 1.25) to (0.65, 0.5) within optimiser noise, the measured discharges suggest γ near 0.75, and the ADCP 1.1 to 1.25. We adopt the best pair on the grid, (0.45, 0.75), as the primary law and carry all eight pairs within 0.01 of it in the chain.")
h("3.3 The Gaussian process on A", 2)
p("The target is log A. The inputs are six measured features (position along and across the reach, distance to the nearer bank, relative depth in the section, section mean depth, lateral bed slope). The mean is a weighted least squares on the substrate classes and a wake flag from the field notes. The kernel is an ARD Matérn 3/2 with a white nugget, the per-point noise is fixed from the readings' spread, and the hyperparameters come from the marginal likelihood (stable across restarts). Bank distance alone predicts a held-out section better than all six features (CRPS 0.29 against 0.32, better on 12 of 20 sections, p = 0.05). The chain keeps the six because it was built on them, and the paper says what the field is.")
h("3.4 The uncertainty chain", 2)
p(f"Each sample draws the whole reach at once. The GP posterior over every point of every section is one joint draw. A discrepancy term, split into a reach-level part ({ds['common_sd_log']:.2f} in log, the residual day level after the law) and a point-level part ({ds['independent_sd_log']:.2f}), is calibrated so that 95% of held-out points fall in the 95% band (inflation {cal['inflation']:.3f}). The bed (6 cm per point), the stage (1.5 cm, one draw per time for the whole reach), the roughness scale (7 to 16 mm) and the law (drawn uniformly from its set) complete the sample. Shares are width-weighted within a section and length-weighted over the sections. Every number in the results carries a 90% band from this chain.")
h("3.5 The deliverables", 2)
p("The first deliverable is the set of spatial rating curves: the section mean velocity of all 20 sections every two hours through 2025 and 2026 from the stage record, with bands. A 2 m map of the field, from a bed GP on the RTK sections and the bank points, is drawn once as illustration; every number comes from the sections. The second is the ecological number: the share of the wetted width below a velocity threshold, and its threshold-free form, the reach's mean nesting suitability E.")
h("3.6 The nest model and the posterior update", 2)
p(f"Each nest is one 'used' 2 m cell, with the velocity, depth and bank distance the chain gives it on the day the nest was found, and 20 'available' cells are drawn from the wet channel at the same stage. A logistic model then asks what makes a cell used rather than available, each variable with the others held fixed. Bank distance is the strong selector (nests at {s7['nests']['nest_bank_distance_median_m']:.1f} m from the bank against {s7['nests']['wet_cell_bank_distance_median_m']:.1f} m for the channel, partly where the crews searched). Velocity adds nothing until depth is in the model: near the bank the deeper cells are faster, and the nests take the deep-but-slow ones. With depth in, velocity leans against use (the {nb['n_used']} nests alone: {vc['data_alone'][0]:.1f} ± {vc['data_alone'][1]:.1f} log-odds per m/s) and depth for (+{nb['depth_coef_per_m']['data_alone'][0]:.1f} per m). In plain terms, the fish nest in deep water near the bank; with bank set C (logbook entries 30 and 31) the velocity effect is about {abs(vc['data_alone'][0] / vc['data_alone'][1]):.1f} standard errors from zero, so its sign is suggested rather than shown.")
p(f"The prior is the USFWS habitat suitability curve for smallmouth bass spawning (Edwards, Gebhart and Maughan 1983, curve 20110), digitised from the scanned report and fitted by an exponential ({vc['prior'][0]:.1f} per m/s), with its sd set so that the same report's steep adult utilisation curve sits two sd away ({vc['prior'][1]:.1f}). It is weak by design: it carries the sign and the order of magnitude and lets 59 nests move it. The posterior is {vc['posterior'][0]:.1f} ± {vc['posterior'][1]:.1f} per m/s, half use at {nb['v50_m_s_posterior']['median']:.2f} m/s [{nb['v50_m_s_posterior']['ci90'][0]:.2f}, {nb['v50_m_s_posterior']['ci90'][1]:.2f}]. E is the width-weighted mean of the relative use exp(b_v v) over the reach: 1 if the whole reach were still water, 0 if all of it were too fast for a nest. Its band combines the curve's posterior with the velocity chain. The 0.2 m/s convention sits at the 61st percentile of the nests, so it was not far off. The difference is that the rule is now estimated, with a band, and can be updated as nests accumulate.")
# ---------------------------------------------------------------- 4 data
h("4. The data, and what was done to it before any model")
p("The Middle reach: 20 cross-sections, 257 locations, 1,285 hand-held readings at three to five heights above the bed on 11 days over 2025 and 2026; one ultrasonic stage sensor every 10 minutes (MaxBotix), one bed-mounted SonTek ADCP through 2025, RTK elevations on every section (total station in 2025, Reach RS3 in 2026, NAVD88), and 63 nest sites held aside from day one. Each cleaning step is in the logbook with its evidence:")
bullet("Only rows of type 'Transect' enter. The 196 'Other' rows of 2025 were single readings taken while walking, at 0.3 m/s everywhere regardless of flow; they were 61% of the unique points in the old model and produced a false stage effect. Nests are kept aside and thalweg rows are out.", "Row types.")
bullet("In 2025 'Depth' is a rod reading and 'Actual depth' (0.4 × Depth) is the height above the bed; in 2026 'Depth' is the height. Using the right column moves 82 readings by a fifth to a third.", "Heights above the bed.")
bullet("Three points labelled AT06 on 14 July 2025 sit on AT07's line and carry AT07's names (relabel confirmed by the crew). A leading space in ' AT11' was stripped. One entry error (3.6 ft/s at 0.08 ft) is removed by name.", "Labels and entries.")
bullet("The MaxBotix reads low in the afternoon by about 2 cm, a sensor effect rather than the river (it is tied to the hour and vanishes at night). We keep the night readings as truth, remove the daytime pattern with a monthly template built on dry days, drop implausible readings and spikes, and take a 3 h median. Stage is then read at each reading's own time rather than by calendar day, which matters on the days the river was rising.", "The stage record.")
bullet("Smoothed the same way onto the same 10-minute grid, and never used in any fit.", "The ADCP.")
bullet("The RTK water surface on each section, minus the sensor stage at the time, gives one offset per survey session and one water-surface slope for the reach (5 cm per 100 m, residual 1.3 cm). This puts every measured bed on the sensor's datum, and it is the check that one sensor describes the whole reach.", "The RTK tie.")
bullet("Everything is converted once at load; nothing downstream sees feet.", "Units.")
# ---------------------------------------------------------------- 5 results
h("5. Results and the takeaways")
p("Each result is one figure. The numbers are in Table 3, the parameters in Table 2, the ablations in Table 4.")
fig(P / "F1_site_data_target.png", "Figure 1. The site, the data and the target. (a) The 20 sections, the sensor and the ADCP. (b) The stage record in both seasons with the survey days. The surveys covered 0.74 to 1.09 m of a season that reached 1.65 m. (c) Three profiles reduced to one amplitude each. (d) The amplitude rises with stage on the survey days; (e) divided by the law it does not: the place factor A is what the model learns.")
p("Takeaway: one number per place, with its error, is the whole spatial problem. The stage sensor supplies the rest.")
fig(P / "F2_conveyance_field.png", "Figure 2. What is learned. (a) A against bank distance for every location. (b) One section held out and predicted from the other nineteen, with its band. (c) The held-out score by model, sections held out against random folds. (d) The field on a 2 m grid, as illustration.")
p("Takeaway: the field beats the reach mean on 16 of 20 held-out sections (CRPS 0.31 against 0.41; the 95% band covers 93%), and it is mostly at-a-station geometry: bank distance alone does better. Random folds flatter every model, which is why the paper scores sections and days held out.")
fig(P / "F3_stage_law.png", f"Figure 3. One sensor carries the field through time. (a) Day levels before and after the law. (b) The ADCP through 2025, never used in the fit, read as a single 25° beam, against the chain at its own cell: level ratio {ab['level_ratio_record_over_field_median']:.2f}, MAE {ab['MAE_m_s']*1000:.0f} mm/s, the band covers every two-hour mean to 1.20 m of stage. (c) The 1,208 readings on held-out days predicted at their own height. (d) Continuity: every section's modelled discharge at common stages, the measured discharges on the survey days, and the rating through them.")
p(f"Takeaway: the day effect is stage. The readings on held-out days come back to 0.082 m/s against a deviation of 0.119, the section means on held-out days fall inside the band 20 of 20 times, the 20 measured discharges lie on one rating with {rr['scatter_pct']:.0f}% scatter, and the ADCP validates field and law continuously at one point (reading Vb as a beam, which the instrument's configuration has to confirm).")
fig(P / "F4_spatial_rating_curves.png", "Figure 4. Spatial rating curves. (a, b) The mean velocity of every section every two hours in 2025 and 2026. Ticks mark the hours outside the surveyed stage range. (c) Three sections' rating curves with bands, extrapolation hatched. (d) What the band is made of: inside the range the field and the day-to-day discrepancy, above it the law set.")
p("Takeaway: this is the deliverable. Bands are about ±28% inside the surveyed range and widen above it because the law is a ridge, which the figure shows and the discussion states once.")
fig(P / "F5_ecological_number.png", "Figure 5. The ecological number, learned from the nests. (a, b) The reach's mean nesting suitability E and the share below 0.2 m/s every two hours, both seasons, with bands. (c) The ecological rating curve: habitat against stage, E with its band and the share below four thresholds; the surveyed range is shaded and the extrapolation hatched. (d) The velocity effect: the published curve as a weak prior, the nests alone, and the posterior.")
p(f"Takeaway: the ecological rating curve is the number the sensor delivers. Every 10 cm of stage removes about 8 points of slow water from the reach inside the surveyed range, and E falls from about 67% at 0.65 m to 21% at 1.30 m. E has median {nb['reach_mean_suitability']['2025']['median']*100:.0f}% in 2025 and {nb['reach_mean_suitability']['2026']['median']*100:.0f}% in 2026 (the share below 0.2 m/s: {s7['season']['2025']['median_share']*100:.0f}% and {s7['season']['2026']['median_share']*100:.0f}%). The rule is estimated with a band rather than assumed; what the nests select on (deep, slow water near the bank) is in the supplementary figure 12.")
h("5.1 Validation scores (Table 3)", 2); table(t3, widths=[2.0, 2.8, 1.7], font=8)
h("5.2 Parameters and settings (Table 2)", 2); table(t2, widths=[1.1, 1.3, 3.0, 1.1], font=7.5)
h("5.3 Ablations (Table 4)", 2); table(t4, font=8)
# ---------------------------------------------------------------- 6 SI
h("6. Supplementary information (candidates)")
p(f"Figures in {FOLDER}/figures/, one line each, with the logbook entry that made them in brackets.")
for f_, c_ in [("00a_map.png, 00b_stage_discharge.png, 00c_adcp.png, 00d_profiles.png", "the data at a glance (entry 2)"), ("00e_stage_diurnal.png, 00g_stage_night.png, 00h_stage_full.png, 00i_stage_steps.png, 00k_full_series.png", "the stage record: the daytime artefact, the night line, the correction, both seasons (entries 3 to 6)"), ("00l_field_inputs.png, 00m_logprofile.png, 00o_amplitude_checks.png, figures/profiles/", "the profiles and the amplitude, every location (entries 7 and 9)"), ("00q_rtk_datum.png", "the RTK tie to the sensor datum (entry 10)"), ("00v_features.png", "the candidate features and how A responds to each (entry 13)"), ("17_model_variables.png", "Figure M, the variables (this document)"), ("02_step2_conveyance_gp.png, step2_feature_ablation.csv, step2_kernel_ablation.csv", "the GP, sections held out, the ablations (entries 15, 22)"), ("03_step3_transfer.png, 03b_law_refine.png", "the day effect, the laws, the (h0, γ) grid (entries 16, 17)"), ("04_step4_uncertainty.png", "the uncertainty chain: calibration and attribution at four stages on four sections (entry 17)"), ("05_step5_map.png", "the bed GP, the grid, the map against the sections (entry 18)"), ("06_step6_rating_curves.png", "the section series, continuity, the validation table (entry 19)"), ("07_step7_ecology.png, 10_nest_habitat.png, 11_nest_bayes.png, 12_nest_selection_explained.png", "the ecological number, the nest-calibrated thresholds, the selection model explained, the Bayesian suitability (entries 20, 23)"), ("09_adcp_single_beam.png, adcp_recheck.json", "the ADCP re-read and the single-beam test (entry 23)"), ("reviews/, LOGBOOK.md entry 22", "the three reviewer reports and the responses")]: bullet(c_, f_ + ":")
p("Two supplementary figures worth showing in full. The per-location profile pages (figures/profiles/page_01 to page_06 and profiles_all.pdf) draw every one of the 257 locations' readings with its fitted log law: the busy one, and the one that answers 'how did you get one number per location'. Page 1 is below; the other pages are in the folder.")
fig(FIG / "profiles" / "page_01.png", "Supplementary figure: the log-law fit at every location, page 1 of 6 (figures/profiles/). Each small panel is one location on one day: its readings against height above the bed, the fitted curve v = a ln(z/z0) with the reach's z0, the amplitude a it yields, and the fit's R². The remaining pages cover the other locations.", width=6.6)
fig(FIG / "07_step7_ecology.png", "Supplementary figure: the ecological number in full (figure 07): the share below 0.2 m/s every two hours in both seasons, the ecological rating curve for the depth-averaged and the near-bed reference and for five thresholds, and the nests against the available channel. Panel c of Figure 5 is drawn from the same tables.", width=6.6)
p("Data repository: data_raw/ (the raw sheets and sensor exports as used), data_clean/ (every derived table), the scripts, requirements_frozen.txt, run_all.sh and the logbook. The folder is self-contained and reruns in about ten minutes; the rerun of 22 September 2026 reproduced every number in this document.")
# ---------------------------------------------------------------- 7 directions
h("7. Directions for writing the paper")
bullet("Environmental Modelling and Software, or Water Resources Research on the methods side. The reader is a modeller or a practitioner with a stage sensor. The abstract states the question, the method, how it was evaluated and what carries over; STORY.md holds draft 4.", "Journal and reader.")
bullet("Five figures, one message each, as above. Everything else is supplementary. Resist adding panels.", "Figures.")
bullet("(i) One profile becomes one physical number. (ii) A one-parameter law separates the day from the place. (iii) The place factor is learnable from geometry. (iv) One sensor carries it through two seasons, tested five ways. (v) The ecological rule is learned from the fish, with a band. Each claim has a figure and a table row.", "The claims, with their evidence.")
bullet("The law's exponent above the surveyed stage range is a ridge, and the band shows it. The wetted width stops at the outermost surveyed points, so the share is a lower bound at high stage. Day and place are confounded in the survey design, and the continuity of the measured discharges is the place-free evidence. The nests validate the margin rather than the field within it. Each of these is said once, in the discussion, and the paper moves on.", "The limits, stated once.")
bullet("Vb as a single beam (the instrument's configuration); the meter's make; a source for the 0.2 m/s convention, now only a comparison. Everything else is in hand.", "Pending from the field team.")
bullet("Interleave sections across days and repeat a few of them; put the sensor inside the surveyed stretch; know what the fixed instrument measures before it goes in. These come straight from what worked in the Middle and what did not in the other two reaches.", "Design lessons for the last section.")
bullet("Their survey and sensor data are in the repository and the scripts exist. The work is paused because the Lower's record needs the Middle's cleaning and both sensors sit outside their surveyed stretches; entries 21 and 24 of the logbook and OPEN_QUESTIONS.md carry the instructions.", "The other two reaches.")
h("8. Rerunning and checking")
p("RERUN.md in the folder gives the environment, the one command, the numbers to compare, and a prompt a Claude Code session can run to verify the work independently. To that end, everything the paper will say can be regenerated by anyone on the team in a few minutes.")
doc.save(P / "METHODS_AND_RESULTS.docx"); open(P / "METHODS_AND_RESULTS.md", "w").write("\n".join(MD)); print("saved", P / "METHODS_AND_RESULTS.docx", "and .md")
